-- ==================================================================
-- Migration 017: Offline classroom courses, offers, fee items and subject-wise syllabus
-- 1. courses: course type "offline", admission through the Apply Now form (admission_mode = enquiry),
--    an optional offer window for the sale price (offer_starts_at / offer_ends_at), fee items
--    (admission, registration and other fee options - never added together), a subject-wise
--    syllabus and extra page sections (exam details, preparation strategy …), all edited in admin → Courses.
-- 2. enquiries: WhatsApp number and education qualification from the course admission form.
-- 3. Course catalogue from the owner's fee sheet (November 2026): 7 categories and 11 courses. Every
--    course that was published before is archived (hidden from the website; enrolled students keep access).
-- Plain SQL that runs on MySQL 8 and MariaDB. Apply from admin → System → Database Updates
-- (re-running is safe: "already exists" / duplicate errors are skipped there).
-- Generated by a script: course texts are JSON inside SQL strings (backslashes and quotes escaped).
-- ==================================================================
SET NAMES utf8mb4;

-- 1. Courses: offline type, admission mode, offer window, fees, syllabus, page sections
ALTER TABLE courses MODIFY course_type ENUM('free','paid','recorded','live','hybrid','offline') NOT NULL DEFAULT 'paid';

ALTER TABLE courses
    ADD COLUMN admission_mode ENUM('online','enquiry') NOT NULL DEFAULT 'online' COMMENT 'enquiry = Apply Now form, no online checkout' AFTER course_type,
    ADD COLUMN offer_starts_at DATETIME NULL COMMENT 'sale price applies from (NULL = already running)' AFTER discount_price,
    ADD COLUMN offer_ends_at DATETIME NULL COMMENT 'sale price applies until (NULL = no end)' AFTER offer_starts_at,
    ADD COLUMN fee_items LONGTEXT NULL COMMENT 'JSON [{group, label, amount, note, offer_free}]' AFTER highlights,
    ADD COLUMN syllabus LONGTEXT NULL COMMENT 'JSON [{title, topics: [..]}] subject-wise syllabus' AFTER fee_items,
    ADD COLUMN info_sections LONGTEXT NULL COMMENT 'JSON [{title, body}] extra course page sections' AFTER syllabus;

-- 2. Enquiries: admission form details
ALTER TABLE enquiries
    ADD COLUMN whatsapp VARCHAR(20) NULL AFTER phone,
    ADD COLUMN qualification VARCHAR(120) NULL AFTER whatsapp;

-- 3a. Categories: three new ones (existing Railway, SSC, Banking and Police are reused)
