UPDATE course_categories SET sort_order = 2, description = 'RRB ALP, Technician, NTPC and Group D exam preparation.' WHERE slug = 'railway';
UPDATE course_categories SET sort_order = 3, description = 'SSC CGL, CHSL, MTS and GD Constable exam preparation.' WHERE slug = 'ssc';
UPDATE course_categories SET sort_order = 4, description = 'IBPS and bank PO and clerk exam preparation.' WHERE slug = 'banking';
UPDATE course_categories SET sort_order = 5, description = 'Delhi Police constable exam preparation.' WHERE slug = 'police';
-- Categories without courses stay active (mock tests and job alerts use them) but are hidden from the course menus.
UPDATE course_categories SET sort_order = sort_order + 20 WHERE slug NOT IN ('govt-job-foundation', 'railway', 'ssc', 'banking', 'police', 'state-govt-exams', 'subject-foundation') AND sort_order < 20;

-- 3b. Previous courses: archived (owner: "add these courses only, remove the earlier ones")
UPDATE courses SET status = 'archived', is_featured = 0 WHERE status = 'published' AND slug NOT IN ('all-government-job-foundation', 'railway-alp-technician', 'railway-ntpc-group-d', 'ssc-cgl-chsl-mts-gd', 'bank-ibps', 'delhi-police', 'state-government-exam', 'mathematics-foundation', 'reasoning-foundation', 'gk-gs-foundation', 'english-foundation');

